mapper.select:
select

 from survey_zha_org_assess a
 where a.zha_assess_id = #{zhaAssessId,jdbcType=BIGINT}

     and a.survey_org_id = #{surveyOrgId,jdbcType=BIGINT}


    and a.is_sun = #{isSun,jdbcType=INTEGER}

 order by a.survey_org_id

update.foreach:
update survey_zha_org_assess
survey_org_id = #{item.surveyOrgId}, survey_org_name = #{item.surveyOrgName}, survey_no = #{item.surveyNo}, survey_info_id = #{item.surveyInfoId}, survey_person = #{item.surveyPerson}, survey_submit_money = #{item.surveySubmitMoney}, is_sun = #{item.isSun}
where id = #{item.id}
